public class DatabaseConnectionExample {
    public static void main(String[] args) {
        // PostgreSQL connection URL (default port 5432)
        String postgresUrl = "jdbc:postgresql://localhost:5432/mydb";

        // MySQL connection URL (default port 3306)
        String mysqlUrl = "jdbc:mysql://localhost:3306/mydb";

        // Adding connection properties to the URL
        String mysqlUrlWithParams = "jdbc:mysql://localhost:3306/mydb?useSSL=false&serverTimezone=UTC";

        // PostgreSQL with schema specification
        String postgresUrlWithSchema = "jdbc:postgresql://localhost:5432/mydb?currentSchema=public";

        // Remote database connection
        String remoteUrl = "jdbc:postgresql://db.example.com:5432/production_db";

        // In production, this URL comes from application.properties:
        // spring.datasource.url=jdbc:postgresql://localhost:5432/mydb
    }
}

@Repository
public class OrderRepository {
    private final DataSource dataSource;

    public OrderRepository(DataSource dataSource) {
        this.dataSource = dataSource;
    }

    public List<Order> findOrdersByCustomerId(Long customerId) {
        var orders = new ArrayList<Order>();
        String sql = "SELECT id, item, amount FROM orders WHERE customer_id = ?";

        // All three resources closed automatically in reverse order
        try (Connection conn = dataSource.getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {

            stmt.setLong(1, customerId);

            try (ResultSet rs = stmt.executeQuery()) {
                while (rs.next()) {
                    orders.add(new Order(
                        rs.getLong("id"),
                        rs.getString("item"),
                        rs.getBigDecimal("amount")
                    ));
                }
            }
        } catch (SQLException e) {
            throw new RuntimeException("Failed to fetch orders", e);
        }
        return orders; // Connection already closed here, even if exception occurred
    }
}

