@Service
public class CustomerService {
    private final DataSource dataSource; // HikariCP DataSource injected by Spring

    public CustomerService(DataSource dataSource) {
        this.dataSource = dataSource;
    }

    public Customer findCustomerById(Long id) {
        String sql = "SELECT id, name, email FROM customers WHERE id = ?";

        // getConnection() borrows from the pool (fast - no TCP handshake)
        try (Connection conn = dataSource.getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {

            stmt.setLong(1, id);
            try (ResultSet rs = stmt.executeQuery()) {
                if (rs.next()) {
                    return new Customer(rs.getLong("id"), rs.getString("name"), rs.getString("email"));
                }
            }
        } catch (SQLException e) {
            throw new RuntimeException("Failed to fetch customer", e);
        }
        return null;
        // Connection returned to pool here - ready for next request
    }
}

