@Service
public class UserService {
    private final DataSource dataSource; // Spring Boot auto-configured from properties

    public UserService(DataSource dataSource) {
        this.dataSource = dataSource;
    }

    public User findUserByEmail(String email) {
        // DataSource already configured - just use it
        String sql = "SELECT id, email, name FROM users WHERE email = ?";

        try (Connection conn = dataSource.getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {

            stmt.setString(1, email);
            try (ResultSet rs = stmt.executeQuery()) {
                if (rs.next()) {
                    return new User(rs.getLong("id"), rs.getString("email"), rs.getString("name"));
                }
            }
        } catch (SQLException e) {
            throw new RuntimeException("Database query failed", e);
        }
        return null;
    }
}

@Configuration
public class DatabaseConfig {

    // PostgreSQL URL with schema and SSL settings
    public DataSource postgresDataSource() {
        var config = new HikariConfig();
        config.setJdbcUrl("jdbc:postgresql://db.example.com:5432/production_db?currentSchema=sales&ssl=true");
        config.setUsername("app_user");
        config.setPassword("secret_password");
        return new HikariDataSource(config);
    }

    // MySQL URL with timezone and SSL configuration
    public DataSource mysqlDataSource() {
        var config = new HikariConfig();
        config.setJdbcUrl("jdbc:mysql://localhost:3306/mydb?useSSL=false&serverTimezone=UTC&allowPublicKeyRetrieval=true");
        config.setUsername("root");
        config.setPassword("root_password");
        return new HikariDataSource(config);
    }

    // Oracle URL format (different structure)
    public DataSource oracleDataSource() {
        var config = new HikariConfig();
        config.setJdbcUrl("jdbc:oracle:thin:@localhost:1521:orcl");
        config.setUsername("system");
        config.setPassword("oracle_password");
        return new HikariDataSource(config);
    }
}

@Repository
public class ProductRepository {
    private final DataSource dataSource;

    public ProductRepository(DataSource dataSource) {
        this.dataSource = dataSource;
    }

    // CORRECT: try-with-resources guarantees connection closes
    public Optional<Product> findProductById(Long id) {
        String sql = "SELECT id, name, price FROM products WHERE id = ?";

        // All three resources close automatically in reverse order
        try (Connection conn = dataSource.getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {

            stmt.setLong(1, id);

            try (ResultSet rs = stmt.executeQuery()) {
                if (rs.next()) {
                    return Optional.of(new Product(
                        rs.getLong("id"),
                        rs.getString("name"),
                        rs.getBigDecimal("price")
                    ));
                }
            }
        } catch (SQLException e) {
            throw new RuntimeException("Failed to fetch product", e);
        }
        return Optional.empty();
        // Connection returned to pool here - even if exception occurred above
    }

    // WRONG: connection leaks if exception happens before close()
    public Product findProductByIdWrong(Long id) throws SQLException {
        Connection conn = dataSource.getConnection();
        PreparedStatement stmt = conn.prepareStatement("SELECT * FROM products WHERE id = ?");
        stmt.setLong(1, id);
        ResultSet rs = stmt.executeQuery();
        // If exception occurs here, close() never executes - connection leaked!
        Product product = mapResultSet(rs);
        conn.close(); // This line never runs if mapResultSet throws exception
        return product;
    }
}

// pom.xml - Maven dependency for PostgreSQL JDBC driver (Type 4)
// <dependency>
//     <groupId>org.postgresql</groupId>
//     <artifactId>postgresql</artifactId>
//     <version>42.6.0</version>
// </dependency>

// The driver registers itself when the JAR is loaded
// No need for Class.forName("org.postgresql.Driver") in modern JDBC

@Configuration
public class DataSourceConfiguration {

    @Bean
    public DataSource dataSource() {
        var config = new HikariConfig();

        // The "postgresql" subprotocol tells DriverManager to use PostgreSQL driver
        config.setJdbcUrl("jdbc:postgresql://localhost:5432/mydb");
        config.setUsername("dbuser");
        config.setPassword("dbpassword");

        // HikariCP finds the PostgreSQL driver automatically from the classpath
        return new HikariDataSource(config);
    }
}

@Service
public class OrderService {
    private final DataSource dataSource;

    public OrderService(DataSource dataSource) {
        this.dataSource = dataSource;
    }

    public List<Order> getAllOrders() {
        var orders = new ArrayList<Order>();

        // When getConnection() is called, the driver establishes the actual TCP connection
        try (Connection conn = dataSource.getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery("SELECT id, total FROM orders")) {

            while (rs.next()) {
                orders.add(new Order(rs.getLong("id"), rs.getBigDecimal("total")));
            }
        } catch (SQLException e) {
            throw new RuntimeException("Failed to fetch orders", e);
        }
        return orders;
    }
}
